package io.github.sammeeeeeeee.onenet

/** Signal glyphs shared by the tile and the panel; generated by tools/gen_icons.py. */
object Icons {

    private val WIFI = intArrayOf(
        R.drawable.ic_qs_wifi_0, R.drawable.ic_qs_wifi_1, R.drawable.ic_qs_wifi_2,
        R.drawable.ic_qs_wifi_3, R.drawable.ic_qs_wifi_4,
    )
    private val WIFI_NO_INTERNET = intArrayOf(
        R.drawable.ic_qs_wifi_no_internet_0, R.drawable.ic_qs_wifi_no_internet_1,
        R.drawable.ic_qs_wifi_no_internet_2, R.drawable.ic_qs_wifi_no_internet_3,
        R.drawable.ic_qs_wifi_no_internet_4,
    )
    private val CELL = intArrayOf(
        R.drawable.ic_qs_cell_0, R.drawable.ic_qs_cell_1, R.drawable.ic_qs_cell_2,
        R.drawable.ic_qs_cell_3, R.drawable.ic_qs_cell_4,
    )
    private val CELL_NO_INTERNET = intArrayOf(
        R.drawable.ic_qs_cell_no_internet_0, R.drawable.ic_qs_cell_no_internet_1,
        R.drawable.ic_qs_cell_no_internet_2, R.drawable.ic_qs_cell_no_internet_3,
        R.drawable.ic_qs_cell_no_internet_4,
    )

    /** [level] is 0..4. */
    fun wifi(level: Int, noInternet: Boolean = false) =
        (if (noInternet) WIFI_NO_INTERNET else WIFI)[level.coerceIn(0, 4)]

    fun cell(level: Int, noInternet: Boolean = false) =
        (if (noInternet) CELL_NO_INTERNET else CELL)[level.coerceIn(0, 4)]
}
